describe('Notification Count Reset', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should reset notification count to zero after reading all messages', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('fetchNotifications');
    cy.wait('@fetchNotifications');

    // Verify initial notification count is displayed
    cy.get('[data-testid="notification-count"]').should('be.visible');
    cy.get('[data-testid="notification-count"]').should('contain', '5');

    // Read the first notification
    cy.get('[data-testid="notification-item-1"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases
    cy.get('[data-testid="notification-count"]').should('contain', '4');

    // Read the second notification
    cy.get('[data-testid="notification-item-2"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases again
    cy.get('[data-testid="notification-count"]').should('contain', '3');

    // Read the third notification
    cy.get('[data-testid="notification-item-3"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases once more
    cy.get('[data-testid="notification-count"]').should('contain', '2');

    // Read the fourth notification
    cy.get('[data-testid="notification-item-4"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases to zero
    cy.get('[data-testid="notification-count"]').should('contain', '0');

    // Verify notification count is now zero
    cy.get('[data-testid="notification-count"]').should('contain', '0');

    // Verify notification list is empty
    cy.get('[data-testid="notification-item"]').should('not.exist');
  });

  it('should not reset notification count when there are unread notifications', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('fetchNotifications');
    cy.wait('@fetchNotifications');

    // Verify initial notification count is displayed
    cy.get('[data-testid="notification-count"]').should('be.visible');
    cy.get('[data-testid="notification-count"]').should('contain', '5');

    // Read the first notification
    cy.get('[data-testid="notification-item-1"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases
    cy.get('[data-testid="notification-count"]').should('contain', '4');

    // Read the second notification
    cy.get('[data-testid="notification-item-2"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases again
    cy.get('[data-testid="notification-count"]').should('contain', '3');

    // Read the third notification
    cy.get('[data-testid="notification-item-3"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases to 2
    cy.get('[data-testid="notification-count"]').should('contain', '2');

    // Read the fourth notification
    cy.get('[data-testid="notification-item-4"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases to 1
    cy.get('[data-testid="notification-count"]').should('contain', '1');

    // Read the fifth notification
    cy.get('[data-testid="notification-item-5"]').should('be.visible');
    cy.get('[data-testid="read-notification-btn"]').click();

    // Verify notification count decreases to 0
    cy.get('[data-testid="notification-count"]').should('contain', '0');

    // Verify notification list is empty
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify notification count does not reset to zero when there are unread notifications
    cy.get('[data-testid="notification-count"]').should('contain', '0');
  });
});
